    """
    Returns a list of strings where each string is either 'Fizz', 'Buzz', 'FizzBuzz' or the number itself.
    'Fizz' is used for multiples of 3, 'Buzz' for multiples of 5, and 'FizzBuzz' for multiples of both.

    Args:
        n (int): The upper limit of the range (inclusive).

    Returns:
        list[str]: A list of strings as described above.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
